<template><view class="page"><view class="page-title">报名成员</view><view v-for="m in members" :key="m.userId" class="card"><view class="row-between"><view><view class="section-title">{{ m.nickname }}</view><view class="muted">{{ m.username }} · {{ m.grade||'未填写年级' }}</view><view class="muted">乘车人数：{{ m.passengerCount||'未填写' }} 备注：{{ m.remark||'无' }}</view></view><button size="mini" class="mini-primary" @click="transfer(m.userId)">转让团长</button></view></view><view v-if="!members.length" class="empty">暂无成员</view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad,onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import type{Member}from'@/services/types';const id=ref(0),members=ref<Member[]>([]);onLoad((o:any)=>id.value=Number(o.id));onShow(load);async function load(){if(id.value)members.value=await api(`/activities/${id.value}/signups`)}function transfer(userId:number){uni.showModal({title:'转让团长',content:'确认将团长身份转让给该成员？',success:async r=>{if(r.confirm){await api(`/activities/${id.value}/transfer`,'POST',{newCreatorId:userId});uni.showToast({title:'转让成功'});setTimeout(()=>uni.navigateBack(),500)}}})}</script>
